#include <algorithm>
#include <cctype>

using namespace std;

// 函数：清理字符串，移除标点符号并转换为小写
string cleanWord(string word) {
    string cleaned = "";
    for (char c : word) {
        if (isalnum(c)) { // 只保留字母和数字
            cleaned += tolower(c);
        }
    }
    return cleaned;
}

int main() {
    string text;
    cout << "请输入一段文本: ";
    getline(cin, text);

    // 使用 unordered_map 来存储单词及其出现次数
    // Key: 单词 (string), Value: 次数 (int)
    unordered_map<string, int> wordCount;

    stringstream ss(text);
    string word;

    while (ss >> word) {
        string cleaned = cleanWord(word);
        if (!cleaned.empty()) {
            wordCount[cleaned]++;
        }
    }

    cout << "\n单词出现次数统计:\n";
    cout << "----------------------------\n";
    for (auto const& [val, count] : wordCount) {
        cout << val << ": " << count << endl;
    }

    return 0;
}
