#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <cctype>

using namespace std;

// Function to clean a word by removing punctuation and converting to lowercase
string cleanWord(string word) {
    string cleaned = "";
    for (char c : word) {
        if (isalnum(c)) { // Keep only alphanumeric characters
            cleaned += tolower(c);
        }
    }
    return cleaned;
}

int main() {
    string text;
    cout << "Enter a sentence: ";
    getline(cin, text);

    // unordered_map to store word frequencies
    unordered_map<string, int> wordCount;

    stringstream ss(text);
    string word;

    // Split the string by spaces and process each word
    while (ss >> word) {
        string cleaned = cleanWord(word);
        if (!cleaned.empty()) {
            wordCount[cleaned]++;
        }
    }

    cout << "\nWord Frequency Count:\n";
    cout << "----------------------------\n";
    for (auto const& [val, count] : wordCount) {
        cout << val << ": " << count << endl;
    }

    return 0;
}
