#include <algorithm>
#include <cctype>

using namespace std;

// Function to clean a word by removing punctuation and converting to lowercase
string cleanWord(string word) {
    string cleaned = "";
    for (char c : word) {
        if (isalnum(c)) { // Keep only alphanumeric characters
            cleaned += tolower(c);
        }
    }
    return cleaned;
}

int main() {
    string text;
    cout << "Enter a sentence: ";
    getline(cin, text);

    // unordered_map to store word frequencies
    unordered_map<string, int> wordCount;

    stringstream ss(text);
    string word;

    // Split the string by spaces and process each word
    while (ss >> word) {
        string cleaned = cleanWord(word);
        if (!cleaned.empty()) {
            wordCount[cleaned]++;
        }
    }

    cout << "\nWord Frequency Count:\n";
    cout << "----------------------------\n";
    for (auto const& [val, count] : wordCount) {
        cout << val << ": " << count << endl;
    }

    return 0;
}
```

### Explanation:
1.  **`std::unordered_map`**: I used an `unordered_map` because it provides average $O(1)$ time complexity for insertions and lookups, making it very efficient for counting.
2.  **`std::stringstream`**: This is a convenient way to split a string into words based on whitespace.
3.  **`cleanWord` function**: This ensures that "Apple," "apple!", and "apple" are all treated as the same word by removing non-alphanumeric characters and converting everything to lowercase.
4.  **`getline`**: Used instead of `cin >>` to ensure the entire line of text (including spaces) is captured.

### Complexity:
*   **Time Complexity**: $O(N)$, where $N$ is the total number of characters in the input string.
*   **Space Complexity**: $O(W)$, where $W$ is the number of unique words stored in the map.

### Example Run:
**Input**: `Hello world! Hello C++, welcome to the world of C++`
**Output**:
```
hello: 2
world: 2
c: 2
welcome: 1
to: 1
the: 1
of: 1
```
*(Note: The output order may vary because `unordered_map` does not maintain insertion order.)*

### Key C++ Concepts Used:
*   **`std::unordered_map`**: A hash table implementation for fast key-value storage.
*   **`std::stringstream`**: Used to parse the input string into individual words.
*   **`std::tolower`**: Used to normalize the case of the words.
*   **`std::isalnum`**: Used to filter out punctuation.
*   **Structured Bindings (C++17)**: The `for (auto const& [val, count] : wordCount)` syntax allows easy iteration over map pairs.

